const kb = [{"tags": "tell me about yourself intro hr", "q": "Tell me about yourself", "a": "Use Present-Past-Future in 60-90 sec. Present: branch, year, key skill. Past: 1-2 projects/internships with a result. Future: why this role. Mistake: reciting the resume or family background."}, {"tags": "strengths weaknesses hr", "q": "What are your strengths and weaknesses?", "a": "Pick 2 strengths with proof (e.g. quick learner: built X in 2 weeks). Weakness must be real but fixable, with the steps you are taking (e.g. public speaking: joined a club). Avoid 'I am a perfectionist'."}, {"tags": "why should we hire you hr", "q": "Why should we hire you?", "a": "Match your skills to the job description, add one proof point, show enthusiasm to learn. Keep it 45 seconds."}, {"tags": "5 years goals hr", "q": "Where do you see yourself in 5 years?", "a": "Show growth within the company: become strong in the domain, take ownership of projects, maybe mentor others. Avoid mentioning higher studies or switching."}, {"tags": "oops oop object oriented technical", "q": "Four pillars of OOP", "a": "Encapsulation (bundle data+methods, hide state), Abstraction (expose only essentials), Inheritance (reuse via parent-child), Polymorphism (same interface, different behaviour: overloading/overriding). Give a real example like Vehicle -> Car/Bike."}, {"tags": "dbms sql normalization technical", "q": "Explain normalization and ACID", "a": "Normalization reduces redundancy: 1NF atomic values, 2NF no partial dependency, 3NF no transitive dependency. ACID = Atomicity, Consistency, Isolation, Durability. Be ready with a bank-transfer example."}, {"tags": "os process thread deadlock technical", "q": "Process vs thread, and deadlock", "a": "Process has its own memory; threads share memory within a process. Deadlock needs 4 conditions: mutual exclusion, hold and wait, no preemption, circular wait. Break any one to prevent it."}, {"tags": "dsa array linked list sorting coding technical", "q": "Top DSA topics for placements", "a": "Arrays, strings, hashing, two pointers, sorting/searching, linked list, stack/queue, recursion, trees, basic DP. Practice 150-200 problems on LeetCode/GeeksforGeeks; focus on easy-medium."}, {"tags": "aptitude quant reasoning verbal", "q": "Aptitude preparation plan", "a": "Quant: percentages, profit-loss, time-work, speed-distance, P&C. Reasoning: series, seating, blood relations, puzzles. Verbal: reading comprehension, grammar. Do 30 min daily and timed mock tests weekly. Accuracy first, then speed."}, {"tags": "resume cv projects", "q": "How to build a good fresher resume", "a": "One page, ATS-friendly, no photo. Order: education, skills, projects (with tech + measurable result), internships, achievements. Use action verbs. Every project line should answer: what, how, impact. Be ready to explain every word."}, {"tags": "project explain technical hr", "q": "Explain your project", "a": "Structure: problem, your role, tech stack and why, biggest challenge and how you solved it, result, what you'd improve. Expect follow-ups on database, APIs, and edge cases."}, {"tags": "group discussion gd", "q": "Group discussion tips", "a": "Open with a fact or definition, listen, build on others' points, stay calm, keep each point under 30 sec, summarise if you can. Quality beats volume; avoid interrupting."}, {"tags": "questions to ask interviewer end", "q": "Do you have any questions for us?", "a": "Always ask 1-2: What does training look like for freshers? What does success look like in the first 6 months? Never ask about salary or leave first."}, {"tags": "dress code body language etiquette", "q": "Interview etiquette", "a": "Formals, reach 15 min early, firm handshake, eye contact, keep documents in a folder, thank the panel. Be honest: say 'I don't know, but I would approach it by...' instead of bluffing."}];

const q = String(query || '').toLowerCase().split(/\s+/).filter(w => w.length > 2);
const scored = kb.map(e => {
  const hay = (e.tags + ' ' + e.q + ' ' + e.a).toLowerCase();
  return { e, s: q.reduce((n, w) => n + (hay.includes(w) ? 1 : 0), 0) };
}).filter(x => x.s > 0).sort((a, b) => b.s - a.s).slice(0, 3);
if (!scored.length) return 'No match in knowledge base. Try web search or ask the student to clarify.';
return scored.map(x => 'Q: ' + x.e.q + '\nA: ' + x.e.a).join('\n\n');
